            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Concatenacao repetitiva de strings ('s += i.ToString()') e alocacao continua de arrays ('new object[10000]') dentro do Update(). Como strings sao imutaveis no C#, cada concatenacao cria um novo objeto na memoria heap, gerando mais de 8 MB de lixo por frame e forcando coletas do Garbage Collector que congelam o jogo por ate 24.57 ms.\",\"codigo_refatorado\":\"using System; using System.Collections.Generic; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; public int emptyObjects = 0; private readonly List\u003cGameObject\u003e spawnedPool = new List\u003cGameObject\u003e(); private MaterialPropertyBlock propBlock; private static readonly int ColorProp = Shader.PropertyToID(\\\"_Color\\\"); private void Awake() { propBlock = new MaterialPropertyBlock(); } private void Start() { for (int i = 0; i \u003c emptyObjects; i++) { new GameObject(\\\"Empty_\\\" + i); } } private void Update() { if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) SpawnFromPool(); } } private void SpawnFromPool() { GameObject obj = null; for (int i = 0; i \u003c spawnedPool.Count; i++) { if (!spawnedPool[i].activeInHierarchy) { obj = spawnedPool[i]; break; } } if (obj == null) { obj = Instantiate(testPrefab); spawnedPool.Add(obj); } obj.transform.position = UnityEngine.Random.insideUnitSphere * spawnRadius; obj.transform.rotation = Quaternion.identity; obj.SetActive(true); if (useUniqueMaterials && obj.TryGetComponent\u003cRenderer\u003e(out var rend)) { propBlock.SetColor(ColorProp, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(propBlock); } } } }\",\"explicacao_didatica\":\"Pense na memoria do jogo como uma mesa de trabalho. Toda vez que voce junta dois textos com '+' ou cria listas dentro do Update (que roda 60 vezes por segundo), voce joga papeis amassados no chao. O 'Garbage Collector' e o faxineiro: quando o chao fica cheio demais, ele e obrigado a pausar todo o jogo para limpar a bagunca, causando engasgos (travamentos). Para resolver, paramos de criar lixo desnecessario a cada frame e passamos a reciclar nossos objetos.\"},{\"tipo\":\"CPU\",\"causa_raiz\":\"Uso de 'GameObject.FindObjectsOfType\u003cGameObject\u003e()' dentro de loops repetidos no Update(). Esse metodo varre todos os objetos existentes na cena inteira, causando picos de CPU de 380.73 ms e estourando com folga o limite de 16.7 ms do hardware legado.\",\"codigo_refatorado\":\"using System.Collections.Generic; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressCpu = false; private static readonly List\u003cGameObject\u003e SceneRegistry = new List\u003cGameObject\u003e(); public static void Register(GameObject obj) { if (!SceneRegistry.Contains(obj)) SceneRegistry.Add(obj); } public static void Unregister(GameObject obj) { SceneRegistry.Remove(obj); } private void Update() { if (stressCpu) { int total = SceneRegistry.Count; for (int i = 0; i \u003c total; i++) { var go = SceneRegistry[i]; if (go != null) { /* Processamento sem varrer a arvore da cena */ } } } } } }\",\"explicacao_didatica\":\"O comando FindObjectsOfType e como procurar uma agulha num palheiro andando por toda a casa a cada milissegundo. Em vez de pedir para a Unity procurar todos os objetos do zero toda hora, criamos uma lista propria onde os objetos se apresentam uma unica vez ao nascer e saem quando destruidos, poupando o processador de buscas lentas.\"}],\"dicas_level_design\":null}",
